changeSet.sql:
CREATE TABLE post_tags ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id BIGINT NOT NULL, post_media_id BIGINT, tagged_profile_id BIGINT NOT NULL, x_position DOUBLE PRECISION, y_position DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
CONSTRAINT POST_TAGS_POST_UQ UNIQUE (post_id, post_media_id, tagged_profile_id), CONSTRAINT POST_TAGS_POST_FK FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE, CONSTRAINT POST_TAGS_MEDIA_FK FOREIGN KEY (post_media_id) REFERENCES post_media(id) ON DELETE CASCADE, CONSTRAINT POST_TAGS_PROFILE_FK FOREIGN KEY (tagged_profile_id) REFERENCES profiles(id) ON DELETE CASCADE );
CREATE INDEX idx_post_tags_post ON post_tags(post_id); CREATE INDEX idx_post_tags_profile ON post_tags(tagged_profile_id);
